package com.example.studentmanagement.service;
import com.example.studentmanagement.entity.Student; import com.example.studentmanagement.repository.StudentRepository; import org.springframework.stereotype.Service; import java.util.List;
@Service public class StudentService { private final StudentRepository repo; public StudentService(StudentRepository r){repo=r;} public List<Student> all(){return repo.findAll();} public Student one(Long id){return repo.findById(id).orElseThrow(()->new RuntimeException("Student not found: "+id));} public Student create(Student s){if(repo.findByEmail(s.getEmail()).isPresent()) throw new IllegalArgumentException("Email already exists"); return repo.save(s);} public Student update(Long id,Student in){Student s=one(id);s.setName(in.getName());s.setEmail(in.getEmail());s.setCourse(in.getCourse());s.setAge(in.getAge());return repo.save(s);} public void delete(Long id){repo.delete(one(id));} }
